#!/bin/bash
# Generated by dsh-super-injector dev_scaffold_plugin.
# Build: compile src/ → lib/ with the dsh checkout's tsc.
# Requires DSH_CHECKOUT pointing at a dsh source checkout (auto-probe below).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

# DSH_CHECKOUT 探测：环境变量 → 常见路径（home 下 dsh-harness）→ 已安装运行时分发
CHECKOUT="${DSH_CHECKOUT:-}"
MODE="checkout"
if [ -z "$CHECKOUT" ]; then
  for candidate in "$HOME/dsh-harness" "$HOME/dsh" "$HOME/.dsh/dsh-harness"; do
    if [ -d "$candidate/packages" ]; then CHECKOUT="$candidate"; break; fi
  done
fi
# 回退：无源码 checkout 时用已安装的 dsh 分发（node_modules 下含全部类型依赖）
INSTALL="${DSH_INSTALL:-}/usr/local/lib/node_modules/@deepseek-ai/dsh"
if [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT/packages" ]; then
  # Fallback：无 dsh 源码 checkout（只有 npm 安装目录，既无 packages/ 也无 tsc）时，
  # build.sh / dev_build_plugin 会全部失败。只要依赖链接仍在且能找到 tsc，
  # 就直接编译 src → lib，不再强依赖 checkout。
  TSC_FALLBACK=""
  for cand in "$ROOT/node_modules/.bin/tsc" "$HOME/tls/node_modules/typescript/bin/tsc" "$(command -v tsc 2>/dev/null || true)"; do
    if [ -n "$cand" ] && [ -f "$cand" ]; then TSC_FALLBACK="$cand"; break; fi
  done
  if [ -n "$TSC_FALLBACK" ] && [ -d "$ROOT/node_modules/@deepseek-ai" ]; then
    echo "build: no dsh checkout; fallback compile with $TSC_FALLBACK" >&2
    echo "=== Compiling src → lib (fallback) ==="
    node "$TSC_FALLBACK" -p tsconfig.json
    echo "=== Build complete ==="
    exit 0
  fi
  if [ -d "$INSTALL/node_modules/@deepseek-ai/cordis" ] && [ -d "$INSTALL/node_modules/@types/node" ]; then
    CHECKOUT="$INSTALL"
    MODE="install"
  else
    echo "build: cannot locate the dsh checkout (set DSH_CHECKOUT)" >&2
    exit 1
  fi
fi

TSC=""
for cand in "$CHECKOUT/node_modules/.bin/tsc" \
  "/home/ubuntu/coding/open-design/node_modules/.pnpm/typescript@5.9.3/node_modules/typescript/bin/tsc" \
  "/home/ubuntu/coding/open-design/node_modules/.pnpm/typescript@6.0.3/node_modules/typescript/bin/tsc" \
  "$HOME/coding/shizi/node_modules/typescript/bin/tsc"; do
  if [ -f "$cand" ]; then TSC="$cand"; break; fi
done
if [ -z "$TSC" ]; then
  echo "build: no usable tsc found on disk (network install unavailable)" >&2
  exit 1
fi

link_pkg() {
  local target="$2"
  if [ ! -e "$target" ]; then
    echo "build: dependency target missing: $target (skipped)" >&2
    return 0
  fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    const link = path.resolve(process.argv[1]);
    const target = path.resolve(process.argv[2]);
    fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, process.platform === 'win32' ? 'junction' : 'dir');
  " "node_modules/$1" "$target"
}

echo "=== Linking build dependencies (source: $CHECKOUT, mode: $MODE) ==="
mkdir -p node_modules/@deepseek-ai
node -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"
if [ "$MODE" = "checkout" ]; then
  link_pkg cordis "$CHECKOUT/vendor/cordis"
  link_pkg cosmokit "$CHECKOUT/vendor/cosmokit"
  link_pkg schemastery "$CHECKOUT/vendor/schemastery"
  link_pkg @deepseek-ai/dsh-tools "$CHECKOUT/packages/core/tools"
  link_pkg @deepseek-ai/dsh-llm "$CHECKOUT/packages/llm/llm"
  link_pkg @deepseek-ai/dsh-system-prompt "$CHECKOUT/packages/core/system-prompt"
  link_pkg @types/node "$CHECKOUT/node_modules/@types/node"
else
  NM="$CHECKOUT/node_modules"
  # install 模式：这些包已在 node_modules/@deepseek-ai/ 下，链接名须带 scope
  link_pkg @deepseek-ai/cordis "$NM/@deepseek-ai/cordis"
  link_pkg @deepseek-ai/schemastery "$NM/@deepseek-ai/schemastery"
  link_pkg @deepseek-ai/dsh-tools "$NM/@deepseek-ai/dsh-tools"
  link_pkg @deepseek-ai/dsh-llm "$NM/@deepseek-ai/dsh-llm"
  link_pkg @deepseek-ai/dsh-system-prompt "$NM/@deepseek-ai/dsh-system-prompt"
  link_pkg @types/node "$NM/@types/node"
  # 已安装分发把 @standard-schema 顶层平铺（非 .pnpm）
  if [ -d "$NM/@standard-schema/spec" ]; then
    node -e "
      const fs = require('fs');
      const path = require('path');
      fs.rmSync('node_modules/@standard-schema', { recursive: true, force: true });
      fs.mkdirSync('node_modules/@standard-schema', { recursive: true });
      fs.symlinkSync(path.resolve(process.argv[1]), path.resolve('node_modules/@standard-schema/spec'), 'dir');
    " "$NM/@standard-schema/spec"
  fi
fi

STD_SCHEMA=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@standard-schema+spec@*' 2>/dev/null | head -1 || true)
if [ -n "$STD_SCHEMA" ] && [ -d "$STD_SCHEMA/node_modules/@standard-schema/spec" ]; then
  node -e "
    const fs = require('fs');
    const path = require('path');
    fs.rmSync('node_modules/@standard-schema', { recursive: true, force: true });
    fs.mkdirSync('node_modules/@standard-schema', { recursive: true });
    fs.symlinkSync(path.resolve(process.argv[1]), path.resolve('node_modules/@standard-schema/spec'), process.platform === 'win32' ? 'junction' : 'dir');
  " "$STD_SCHEMA/node_modules/@standard-schema/spec"
fi

echo "=== Compiling src → lib (tsc: $TSC) ==="
node "$TSC" -p tsconfig.json
echo "=== Build complete ==="
